## Design Note

Incremental character-by-character state machine: top-level states (BETWEEN, TOP_STR, TOP_CONT, TOP_NUM, TOP_LIT + wait sub-states) dispatch each char in O(1). Containers use a stack + sub-state machine (structural expectations, string/escape tracking, number/literal validation) to find boundaries and detect errors immediately. Value text is accumulated in a list (O(1) append per char) and passed to `json.loads` only once per completed value. Total work is O(n) in characters fed regardless of chunking. Single-threaded per connection; no locking needed.

### solution.py
```python
"""Incremental JSON stream decoder – RFC 8259, stdlib only, Python 3.12."""

import json
from typing import Any

__all__ = ["JSONStreamError", "IncompleteJSONError", "BufferLimitError", "JSONStreamDecoder"]

# ── exceptions ──────────────────────────────────────────────────────────────

class JSONStreamError(ValueError):
    def __init__(self, msg: str = "", offset: int = 0) -> None:
        super().__init__(msg)
        self.offset: int = offset

class IncompleteJSONError(JSONStreamError):
    pass

class BufferLimitError(JSONStreamError):
    pass

# ── character sets ──────────────────────────────────────────────────────────

_WS   = frozenset(" \t\n\r")
_ESC  = frozenset('"\\/bfnrt')
_HEX  = frozenset("0123456789abcdefABCDEF")
_DIG  = frozenset("0123456789")

# ── decoder ─────────────────────────────────────────────────────────────────

class JSONStreamDecoder:
    """Feed raw-text chunks; receive complete top-level JSON values."""

    def __init__(self, *, max_buffer: int = 10_000_000) -> None:
        if not isinstance(max_buffer, int) or isinstance(max_buffer, bool) or max_buffer < 1:
            raise ValueError("max_buffer must be an int >= 1")
        self._max_buffer = max_buffer
        self._off = 0            # absolute offset (next char to be fed)
        self._buf: list[str] = []
        self._blen = 0           # len(self._buf) cached
        self._val_start = 0      # absolute offset of first char of current value
        self._state = "BETWEEN"
        # container bookkeeping
        self._stk: list[str] = []
        self._cs: str | None = None   # container sub-state
        self._u_rem = 0               # remaining hex digits in \uXXXX
        self._str_key = False         # current container string is a key?
        # number sub-state (shared between top-level and container)
        self._ns: str | None = None
        # literal bookkeeping
        self._lit = ""
        self._lp = 0
        # terminal flags
        self._err = False
        self._done = False

    # ── public API ──────────────────────────────────────────────────────────

    def feed(self, chunk: str) -> list[Any]:
        if self._err or self._done:
            raise JSONStreamError("decoder is unusable", self._off)
        if not isinstance(chunk, str):
            raise TypeError(f"expected str, got {type(chunk).__name__}")
        res: list[Any] = []
        for ch in chunk:
            self._tick(ch, res)
        return res

    def close(self) -> list[Any]:
        if self._err or self._done:
            raise JSONStreamError("decoder is unusable", self._off)
        self._done = True
        st = self._state
        if st == "BETWEEN":
            return []
        if st in ("TOP_NUM_WAIT", "TOP_LIT_WAIT"):
            return [json.loads("".join(self._buf))]
        if st == "TOP_NUM":
            if self._ns in ("N_ZERO", "N_INT", "N_FRAC", "N_EXP"):
                return [json.loads("".join(self._buf))]
            raise IncompleteJSONError("incomplete number", self._off)
        if st == "TOP_LIT":
            if self._lp == len(self._lit):
                return [json.loads("".join(self._buf))]
            raise IncompleteJSONError("incomplete literal", self._off)
        # open container / string / escape
        raise IncompleteJSONError("incomplete value", self._off)

    def pending(self) -> int:
        return self._blen

    # ── helpers ─────────────────────────────────────────────────────────────

    def _fail(self, msg: str, off: int) -> None:
        self._err = True
        raise JSONStreamError(msg, off)

    def _emit(self, res: list[Any]) -> None:
        res.append(json.loads("".join(self._buf)))
        self._buf = []
        self._blen = 0

    def _add(self, ch: str) -> None:
        self._buf.append(ch)
        self._blen += 1
        if self._blen > self._max_buffer:
            off = self._val_start + self._max_buffer
            self._err = True
            raise BufferLimitError("buffer limit exceeded", off)

    def _start_val(self, ch: str) -> None:
        self._val_start = self._off - 1  # current char's offset
        self._buf = [ch]
        self._blen = 1
        if self._blen > self._max_buffer:
            off = self._val_start + self._max_buffer
            self._err = True
            raise BufferLimitError("buffer limit exceeded", off)

    # ── top-level dispatcher ────────────────────────────────────────────────

    def _tick(self, ch: str, res: list[Any]) -> None:
        off = self._off
        self._off += 1
        st = self._state

        if st == "BETWEEN":
            self._between(ch, off, res)
        elif st == "TOP_STR":
            self._top_str(ch, off, res)
        elif st == "TOP_ESC":
            self._top_esc(ch, off, res)
        elif st == "TOP_U":
            self._top_u(ch, off, res)
        elif st == "TOP_CONT":
            self._cont(ch, off, res)
        elif st == "TOP_NUM":
            self._top_num(ch, off, res)
        elif st == "TOP_NUM_WAIT":
            self._term(ch, off, res)
        elif st == "TOP_LIT":
            self._top_lit(ch, off, res)
        elif st == "TOP_LIT_WAIT":
            self._term(ch, off, res)

    # ── BETWEEN ─────────────────────────────────────────────────────────────

    def _between(self, ch: str, off: int, res: list[Any]) -> None:
        if ch in _WS:
            return
        if ch == "{":
            self._start_val(ch)
            self._stk = ["{"]
            self._cs = "C_OPEN"
            self._state = "TOP_CONT"
        elif ch == "[":
            self._start_val(ch)
            self._stk = ["["]
            self._cs = "C_OPEN"
            self._state = "TOP_CONT"
        elif ch == '"':
            self._start_val(ch)
            self._state = "TOP_STR"
        elif ch == "-" or ch in _DIG:
            self._start_val(ch)
            self._state = "TOP_NUM"
            self._ns = "N_NEG" if ch == "-" else ("N_ZERO" if ch == "0" else "N_INT")
        elif ch == "t":
            self._start_val(ch); self._state = "TOP_LIT"; self._lit = "true";  self._lp = 1
        elif ch == "f":
            self._start_val(ch); self._state = "TOP_LIT"; self._lit = "false"; self._lp = 1
        elif ch == "n":
            self._start_val(ch); self._state = "TOP_LIT"; self._lit = "null";  self._lp = 1
        else:
            self._fail(f"unexpected character {ch!r}", off)

    # ── top-level string ────────────────────────────────────────────────────

    def _top_str(self, ch: str, off: int, res: list[Any]) -> None:
        self._add(ch)
        if ch == '"':
            self._emit(res); self._state = "BETWEEN"
        elif ch == "\\":
            self._state = "TOP_ESC"
        elif ord(ch) < 0x20:
            self._fail("control character in string", off)

    def _top_esc(self, ch: str, off: int, res: list[Any]) -> None:
        self._add(ch)
        if ch == "u":
            self._state = "TOP_U"; self._u_rem = 4
        elif ch in _ESC:
            self._state = "TOP_STR"
        else:
            self._fail(f"invalid escape \\{ch}", off)

    def _top_u(self, ch: str, off: int, res: list[Any]) -> None:
        self._add(ch)
        if ch in _HEX:
            self._u_rem -= 1
            if self._u_rem == 0:
                self._state = "TOP_STR"
        else:
            self._fail("invalid hex digit in \\u escape", off)

    # ── top-level number ────────────────────────────────────────────────────

    def _top_num(self, ch: str, off: int, res: list[Any]) -> None:
        ns = self._ns
        if ns == "N_NEG":
            if ch == "0":
                self._add(ch); self._ns = "N_ZERO"
            elif ch in _DIG:
                self._add(ch); self._ns = "N_INT"
            else:
                self._fail(f"invalid char after '-': {ch!r}", off)
        elif ns == "N_ZERO":
            if ch == ".":
                self._add(ch); self._ns = "N_DOT"
            elif ch in "eE":
                self._add(ch); self._ns = "N_E"
            elif ch in _WS or ch in '{["':
                self._term(ch, off, res)
            else:
                self._fail(f"invalid char after '0': {ch!r}", off)
        elif ns == "N_INT":
            if ch in _DIG:
                self._add(ch)
            elif ch == ".":
                self._add(ch); self._ns = "N_DOT"
            elif ch in "eE":
                self._add(ch); self._ns = "N_E"
            elif ch in _WS or ch in '{["':
                self._term(ch, off, res)
            else:
                self._fail(f"invalid char in number: {ch!r}", off)
        elif ns == "N_DOT":
            if ch in _DIG:
                self._add(ch); self._ns = "N_FRAC"
            else:
                self._fail(f"expected digit after '.': {ch!r}", off)
        elif ns == "N_FRAC":
            if ch in _DIG:
                self._add(ch)
            elif ch in "eE":
                self._add(ch); self._ns = "N_E"
            elif ch in _WS or ch in '{["':
                self._term(ch, off, res)
            else:
                self._fail(f"invalid char in fraction: {ch!r}", off)
        elif ns == "N_E":
            if ch in "+-":
                self._add(ch); self._ns = "N_ESIGN"
            elif ch in _DIG:
                self._add(ch); self._ns = "N_EXP"
            else:
                self._fail(f"expected digit/sign after 'e': {ch!r}", off)
        elif ns == "N_ESIGN":
            if ch in _DIG:
                self._add(ch); self._ns = "N_EXP"
            else:
                self._fail(f"expected digit after exponent sign: {ch!r}", off)
        elif ns == "N_EXP":
            if ch in _DIG:
                self._add(ch)
            elif ch in _WS or ch in '{["':
                self._term(ch, off, res)
            else:
                self._fail(f"invalid char in exponent: {ch!r}", off)

    # ── top-level literal ───────────────────────────────────────────────────

    def _top_lit(self, ch: str, off: int, res: list[Any]) -> None:
        if self._lp < len(self._lit):
            if ch == self._lit[self._lp]:
                self._add(ch); self._lp += 1
                if self._lp == len(self._lit):
                    self._state = "TOP_LIT_WAIT"
            else:
                self._fail(f"expected {self._lit[self._lp]!r} in literal", off)

    # ── terminator handler (number / literal) ───────────────────────────────

    def _term(self, ch: str, off: int, res: list[Any]) -> None:
        """Handle the terminating character of a top-level number or literal."""
        if ch in _WS:
            self._emit(res); self._state = "BETWEEN"
        elif ch in '{["':
            self._emit(res)
            self._start_val(ch)
            if ch == "{":
                self._stk = ["{"]; self._cs = "C_OPEN"; self._state = "TOP_CONT"
            elif ch == "[":
                self._stk = ["["]; self._cs = "C_OPEN"; self._state = "TOP_CONT"
            else:  # '"'
                self._state = "TOP_STR"
        else:
            self._fail(f"invalid char after number/literal: {ch!r}", off)

    # ── container scanner ───────────────────────────────────────────────────

    def _cont(self, ch: str, off: int, res: list[Any]) -> None:
        self._add(ch)
        cs = self._cs

        if cs == "C_OPEN":
            self._c_open(ch, off, res)
        elif cs == "C_KEY":
            self._c_key(ch, off, res)
        elif cs == "C_COLON":
            self._c_colon(ch, off, res)
        elif cs == "C_VAL":
            self._c_val(ch, off, res)
        elif cs == "C_COMMA":
            self._c_comma(ch, off, res)
        elif cs == "C_STR":
            self._c_str(ch, off, res)
        elif cs == "C_ESC":
            self._c_esc(ch, off, res)
        elif cs == "C_U":
            self._c_u(ch, off, res)
        elif cs == "C_NUM":
            self._c_num(ch, off, res)
        elif cs == "C_LIT":
            self._c_lit(ch, off, res)

    # ── container sub-states ────────────────────────────────────────────────

    def _c_open(self, ch: str, off: int, res: list[Any]) -> None:
        top = self._stk[-1]
        if top == "{":
            if ch == "}":
                self._pop(res)
            elif ch == '"':
                self._str_key = True; self._cs = "C_STR"
            elif ch in _WS:
                pass
            else:
                self._fail(f"expected key or '}}': {ch!r}", off)
        else:  # '['
            if ch == "]":
                self._pop(res)
            else:
                self._c_val_char(ch, off, res)

    def _c_key(self, ch: str, off: int, res: list[Any]) -> None:
        if ch == "}":
            self._pop(res)
        elif ch == '"':
            self._str_key = True; self._cs = "C_STR"
        elif ch in _WS:
            pass
        else:
            self._fail(f"expected key string: {ch!r}", off)

    def _c_colon(self, ch: str, off: int, res: list[Any]) -> None:
        if ch == ":":
            self._cs = "C_VAL"
        elif ch in _WS:
            pass
        else:
            self._fail(f"expected ':': {ch!r}", off)

    def _c_val(self, ch: str, off: int, res: list[Any]) -> None:
        if ch in _WS:
            return
        self._c_val_char(ch, off, res)

    def _c_val_char(self, ch: str, off: int, res: list[Any]) -> None:
        """Start a value inside a container (assumes ch already in buffer)."""
        if ch == "{":
            self._push("{")
        elif ch == "[":
            self._push("[")
        elif ch == '"':
            self._str_key = False; self._cs = "C_STR"
        elif ch == "-" or ch in _DIG:
            self._cs = "C_NUM"
            self._ns = "N_NEG" if ch == "-" else ("N_ZERO" if ch == "0" else "N_INT")
        elif ch == "t":
            self._cs = "C_LIT"; self._lit = "true";  self._lp = 1
        elif ch == "f":
            self._cs = "C_LIT"; self._lit = "false"; self._lp = 1
        elif ch == "n":
            self._cs = "C_LIT"; self._lit = "null";  self._lp = 1
        elif ch in _WS:
            pass
        else:
            self._fail(f"expected value: {ch!r}", off)

    def _c_comma(self, ch: str, off: int, res: list[Any]) -> None:
        if ch == ",":
            self._cs = "C_VAL" if self._stk[-1] == "[" else "C_KEY"
        elif ch == "]" and self._stk[-1] == "[":
            self._pop(res)
        elif ch == "}" and self._stk[-1] == "{":
            self._pop(res)
        elif ch in _WS:
            pass
        else:
            self._fail(f"expected ',' or close: {ch!r}", off)

    def _c_str(self, ch: str, off: int, res: list[Any]) -> None:
        if ch == '"':
            self._cs = "C_COLON" if self._str_key else "C_COMMA"
        elif ch == "\\":
            self._cs = "C_ESC"
        elif ord(ch) < 0x20:
            self._fail("control character in string", off)

    def _c_esc(self, ch: str, off: int, res: list[Any]) -> None:
        if ch == "u":
            self._cs = "C_U"; self._u_rem = 4
        elif ch in _ESC:
            self._cs = "C_STR"
        else:
            self._fail(f"invalid escape \\{ch}", off)

    def _c_u(self, ch: str, off: int, res: list[Any]) -> None:
        if ch in _HEX:
            self._u_rem -= 1
            if self._u_rem == 0:
                self._cs = "C_STR"
        else:
            self._fail("invalid hex digit in \\u escape", off)

    # ── container number ────────────────────────────────────────────────────

    def _c_num(self, ch: str, off: int, res: list[Any]) -> None:
        ns = self._ns
        if ns == "N_NEG":
            if ch == "0":
                self._ns = "N_ZERO"
            elif ch in _DIG:
                self._ns = "N_INT"
            else:
                self._fail(f"invalid char after '-': {ch!r}", off)
        elif ns == "N_ZERO":
            if ch == ".":
                self._ns = "N_DOT"
            elif ch in "eE":
                self._ns = "N_E"
            elif ch in _WS or ch in ",]}":
                self._c_num_end(ch, off, res)
            else:
                self._fail(f"invalid char after '0': {ch!r}", off)
        elif ns == "N_INT":
            if ch in _DIG:
                pass
            elif ch == ".":
                self._ns = "N_DOT"
            elif ch in "eE":
                self._ns = "N_E"
            elif ch in _WS or ch in ",]}":
                self._c_num_end(ch, off, res)
            else:
                self._fail(f"invalid char in number: {ch!r}", off)
        elif ns == "N_DOT":
            if ch in _DIG:
                self._ns = "N_FRAC"
            else:
                self._fail(f"expected digit after '.': {ch!r}", off)
        elif ns == "N_FRAC":
            if ch in _DIG:
                pass
            elif ch in "eE":
                self._ns = "N_E"
            elif ch in _WS or ch in ",]}":
                self._c_num_end(ch, off, res)
            else:
                self._fail(f"invalid char in fraction: {ch!r}", off)
        elif ns == "N_E":
            if ch in "+-":
                self._ns = "N_ESIGN"
            elif ch in _DIG:
                self._ns = "N_EXP"
            else:
                self._fail(f"expected digit/sign after 'e': {ch!r}", off)
        elif ns == "N_ESIGN":
            if ch in _DIG:
                self._ns = "N_EXP"
            else:
                self._fail(f"expected digit after exponent sign: {ch!r}", off)
        elif ns == "N_EXP":
            if ch in _DIG:
                pass
            elif ch in _WS or ch in ",]}":
                self._c_num_end(ch, off, res)
            else:
                self._fail(f"invalid char in exponent: {ch!r}", off)

    def _c_num_end(self, ch: str, off: int, res: list[Any]) -> None:
        """Number inside container just ended; handle ch as post-value char."""
        if ch in _WS:
            self._cs = "C_COMMA"
        elif ch == ",":
            self._cs = "C_VAL" if self._stk[-1] == "[" else "C_KEY"
        elif ch == "]" and self._stk[-1] == "[":
            self._pop(res)
        elif ch == "}" and self._stk[-1] == "{":
            self._pop(res)
        else:
            self._fail(f"unexpected char after number: {ch!r}", off)

    # ── container literal ───────────────────────────────────────────────────

    def _c_lit(self, ch: str, off: int, res: list[Any]) -> None:
        if self._lp < len(self._lit):
            if ch == self._lit[self._lp]:
                self._lp += 1
                if self._lp == len(self._lit):
                    self._cs = "C_COMMA"
            else:
                # char doesn't match; is it a valid post-literal char?
                if ch in _WS or ch in ",]}":
                    self._fail(f"incomplete literal {self._lit[:self._lp]!r}", off)
                else:
                    self._fail(f"expected {self._lit[self._lp]!r} in literal", off)

    # ── container stack ─────────────────────────────────────────────────────

    def _push(self, brace: str) -> None:
        if len(self._stk) >= 1000:
            self._fail("nesting depth exceeds 1000", self._off - 1)
        self._stk.append(brace)
        self._cs = "C_OPEN"

    def _pop(self, res: list[Any]) -> None:
        self._stk.pop()
        if not self._stk:
            self._emit(res)
            self._state = "BETWEEN"
        else:
            self._cs = "C_COMMA"
