### test_solution.py
```python
"""Comprehensive tests for solution.JSONStreamDecoder."""

import math
import pytest
import solution
from solution import (
    JSONStreamError,
    IncompleteJSONError,
    BufferLimitError,
    JSONStreamDecoder,
)


# ── helpers ─────────────────────────────────────────────────────────────────

def feed_all(dec, *chunks):
    """Feed all chunks, collect all returned values."""
    out = []
    for c in chunks:
        out.extend(dec.feed(c))
    return out


def feed_and_close(dec, *chunks):
    """Feed all chunks then close, collecting everything."""
    out = feed_all(dec, *chunks)
    out.extend(dec.close())
    return out


# ── basic values ────────────────────────────────────────────────────────────

class TestBasicValues:
    def test_single_object(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '{"a":1}') == [{"a": 1}]

    def test_single_array(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '[1,2,3]') == [[1, 2, 3]]

    def test_string(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '"hello"') == ["hello"]

    def test_number_int(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '42') == [42]

    def test_number_float(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '3.14') == [3.14]

    def test_number_exp(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '1e10') == [1e10]

    def test_true(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, 'true') == [True]

    def test_false(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, 'false') == [False]

    def test_null(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, 'null') == [None]

    def test_negative_zero(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '-0.0') == [-0.0]
        assert math.copysign(1, feed_and_close(JSONStreamDecoder(), '-0.0')[0]) == -1.0

    def test_negative_int(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '-42') == [-42]

    def test_zero(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '0') == [0]

    def test_big_int(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '123456789012345678901234567890') == [123456789012345678901234567890]

    def test_inf_via_exp(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '1E400') == [float('inf')]

    def test_empty_object(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '{}') == [{}]

    def test_empty_array(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '[]') == [[]]


# ── multiple values ─────────────────────────────────────────────────────────

class TestMultipleValues:
    def test_two_objects(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '{}{}') == [{}, {}]

    def test_space_separated(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '1 2') == [1, 2]

    def test_mixed(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '{}[] "x" 1 true null') == [{}, [], "x", 1, True, None]

    def test_no_separator_after_container(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '{}[]"x"1') == [{}, [], "x", 1]

    def test_number_then_container(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '1[2]') == [1, [2]]

    def test_literal_then_string(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, 'true"x"') == [True, "x"]

    def test_number_then_brace(self):
        d = JSONStreamDecoder()
        assert feed_and_close(d, '1{"a":2}') == [1, {"a": 2}]

    def test_many_small_values_one_chunk(self):
        d = JSONStreamDecoder()
        chunk = " ".join(str(i) for i in range(1000))
        vals = feed_all(d, chunk)
        # last number may still be pending
        vals.extend(d.close())
        assert vals == list(range(1000))


# ── chunking ────────────────────────────────────────────────────────────────

class TestChunking:
    def test_mid_string(self):
        d = JSONStreamDecoder()
        assert feed_all(d, '"hel') == []
