class TestPerformance:
    def test_large_string_chunked(self):
        """8MB string in 64-char chunks should complete in ~1s."""
        import time
        d = JSONStreamDecoder()
        payload = '"' + "x" * (8 * 1024 * 1024) + '"'
        start = time.perf_counter()
        vals = []
        for i in range(0, len(payload), 64):
            vals.extend(d.feed(payload[i:i+64]))
        vals.extend(d.close())
        elapsed = time.perf_counter() - start
        assert len(vals) == 1
        assert len(vals[0]) == 8 * 1024 * 1024
        assert elapsed < 5.0  # generous; should be ~1s

    def test_many_small_values(self):
        """100k small values in one chunk."""
        import time
        d = JSONStreamDecoder()
        chunk = " ".join(str(i) for i in range(100_000))
        start = time.perf_counter()
        vals = d.feed(chunk)
        vals.extend(d.close())
        elapsed = time.perf_counter() - start
        assert len(vals) == 100_000
        assert elapsed < 5.0


